65	async fn write_records(
66	    State(s): State<Arc<Store>>,
67	    Path(collection): Path<String>,
68	    payload: Result<Json<WriteRequest>, axum::extract::rejection::JsonRejection>,
69	) -> Result<Json<Value>, ApiError> {
