1	//! 持久化存储：集合、当前数据状态与不可变版本快照。
2	//!
3	//! 持久化采用“快照文件 + 追加式 WAL”：
4	//! - `snapshot.json` 以“临时文件 + 原子重命名”落盘，包含全部已保存版本及其快照数据、
5	//!   以及保存时刻各集合的当前数据；
6	//! - `wal.log` 逐行追加已确认提交的批量写入（每行一个 JSON，以换行结尾）；
7	//! - 启动时先恢复快照，再顺序重放 WAL；末尾若存在崩溃残留的残缺行则截断，
8	//!   因此未完成（未 fsync）的写入在重启后不会产生任何记录。
9	//!
10	//! 所有提交与保存都在同一把 `Mutex` 下完成，保证线性一致：快照要么包含
11	//! 整批已提交写入，要么完全不包含，不会出现半批数据。
12	
13	use serde::{Deserialize, Serialize};
14	use serde_json::{Map, Value};
15	use std::collections::{BTreeMap, HashMap};
16	use std::fs;
17	use std::io::Write;
18	use std::path::{Path, PathBuf};
19	use std::sync::Mutex;
20	use std::time::{SystemTime, UNIX_EPOCH};
21	
22	/// 一条记录即保留字段顺序的 JSON 对象，主键为其中的 `id` 字段。
23	pub type Record = Map<String, Value>;
24	
25	/// 一次写入被业务规则拒绝：定位到批次内的记录位置、主键（若可识别）与原因。
26	#[derive(Debug, Clone, Serialize)]
27	pub struct Rejection {
28	    pub index: usize,
29	    pub id: Option<String>,
30	    pub reason: String,
31	}
32	
33	/// 写入失败：整批被拒绝（400）或持久化失败（500）。
34	#[derive(Debug)]
35	pub enum BatchError {
36	    Rejected(Rejection),
37	    Persist(String),
38	}
39	
40	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
41	pub enum LookupError {
42	    VersionNotFound,
43	    CollectionNotFound,
44	}
45	
46	#[derive(Debug, Clone, Serialize)]
47	pub struct WriteOutcome {
48	    pub collection: String,
49	    /// 批次中被接受的记录数（等于整批大小）。
50	    pub accepted: usize,
51	    /// 实际新增的记录数（与已有记录完全相同的写入幂等，不计入）。
52	    pub inserted: usize,
53	}
54	
55	#[derive(Debug, Clone, Serialize)]
56	pub struct VersionSummary {
57	    pub id: u64,
58	    /// 保存时间（Unix 纪元毫秒）。
59	    pub saved_at: u64,
60	}
61	
62	#[derive(Debug, Clone, Serialize)]
63	pub struct VersionDetail {
64	    pub id: u64,
65	    pub saved_at: u64,
66	    /// 该版本快照中包含的集合名。
67	    pub collections: Vec<String>,
68	}
69	
70	/// 一个已保存版本的完整只读快照。
71	struct VersionSnap {
72	    id: u64,
73	    saved_at: u64,
74	    data: HashMap<String, Vec<Record>>,
75	}
76	
77	/// WAL 中的事件：已确认提交的一批记录。
78	#[derive(Serialize, Deserialize)]
79	struct CommitEvent {
80	    collection: String,
81	    records: Vec<Record>,
82	}
83	
84	#[derive(Serialize, Deserialize)]
85	struct PersistedCollection {
86	    name: String,
87	    records: Vec<Record>,
88	}
89	
90	#[derive(Serialize, Deserialize)]
91	struct PersistedVersion {
92	    id: u64,
93	    saved_at: u64,
94	    collections: Vec<PersistedCollection>,
95	}
96	
97	/// `snapshot.json` 的完整内容。
98	#[derive(Serialize, Deserialize)]
99	struct PersistedState {
100	    versions: Vec<PersistedVersion>,
101	    collections: Vec<PersistedCollection>,
102	}
103	
104	struct Inner {
105	    /// 各集合的当前数据；Vec 保存提交顺序。
106	    current: BTreeMap<String, Vec<Record>>,
107	    versions: Vec<VersionSnap>,
108	    next_id: u64,
109	    wal: fs::File,
110	}
111	
112	/// 整个服务的状态。
113	pub struct Store {
114	    inner: Mutex<Inner>,
115	    data_dir: PathBuf,
116	}
117	
118	fn now_ms() -> u64 {
119	    SystemTime::now()
120	        .duration_since(UNIX_EPOCH)
121	        .map(|d| d.as_millis() as u64)
122	        .unwrap_or(0)
123	}
124	
125	impl Store {
126	    /// 从数据目录加载或初始化存储，并完成崩溃恢复。
127	    pub fn open(data_dir: impl AsRef<Path>) -> Result<Self, String> {
128	        let data_dir = data_dir.as_ref().to_path_buf();
129	        fs::create_dir_all(&data_dir).map_err(|e| format!("create data dir: {e}"))?;
130	
131	        let mut current: BTreeMap<String, Vec<Record>> = BTreeMap::new();
132	        let mut versions: Vec<VersionSnap> = Vec::new();
133	
134	        // 1. 恢复最近一次快照（若存在）。
135	        let snap_path = data_dir.join("snapshot.json");
136	        if snap_path.exists() {
137	            let bytes = fs::read(&snap_path).map_err(|e| format!("read snapshot: {e}"))?;
138	            let state: PersistedState =
139	                serde_json::from_slice(&bytes).map_err(|e| format!("parse snapshot: {e}"))?;
140	            for c in state.collections {
141	                current.insert(c.name, c.records);
142	            }
143	            for v in state.versions {
144	                versions.push(VersionSnap {
145	                    id: v.id,
146	                    saved_at: v.saved_at,
147	                    data: v
148	                        .collections
149	                        .into_iter()
150	                        .map(|c| (c.name, c.records))
151	                        .collect(),
152	                });
153	            }
154	        }
155	        let next_id = versions.last().map(|v| v.id + 1).unwrap_or(1);
156	
157	        // 2. 重放快照之后的 WAL，并修复崩溃残留的残缺行。
158	        let wal_path = data_dir.join("wal.log");
159	        let mut valid_bytes = 0usize;
160	        if wal_path.exists() {
161	            let content = fs::read_to_string(&wal_path).map_err(|e| format!("read wal: {e}"))?;
162	            let mut rest = content.as_str();
163	            loop {
164	                if rest.is_empty() {
165	                    break;
166	                }
167	                let Some(nl) = rest.find('\n') else {
168	                    // 最后一行没有换行结尾：本服务的提交总是以换行结尾，故必为残缺行。
169	                    break;
170	                };
171	                let line = &rest[..nl];
172	                match serde_json::from_str::<CommitEvent>(line) {
173	                    Ok(event) => {
174	                        apply_commit(&mut current, event.collection, event.records);
175	                        valid_bytes += nl + 1;
176	                        rest = &rest[nl + 1..];
177	                    }
178	                    Err(_) => break,
179	                }
180	            }
181	            if valid_bytes < content.len() {
182	                let f = fs::OpenOptions::new()
183	                    .write(true)
184	                    .open(&wal_path)
185	                    .map_err(|e| format!("repair wal: {e}"))?;
186	                f.set_len(valid_bytes as u64)
187	                    .map_err(|e| format!("repair wal: {e}"))?;
188	                f.sync_all().ok();
189	            }
190	        }
191	
192	        // 3. 打开 WAL 供后续追加。
193	        let wal = fs::OpenOptions::new()
194	            .create(true)
195	            .append(true)
196	            .open(&wal_path)
197	            .map_err(|e| format!("open wal: {e}"))?;
198	
199	        Ok(Store {
200	            inner: Mutex::new(Inner {
201	                current,
202	                versions,
203	                next_id,
204	                wal,
205	            }),
206	            data_dir,
207	        })
208	    }
209	
210	    /// 批量写入：整批校验通过后原子提交，任一条不合法则整批拒绝、已有数据不变。
211	    pub fn write_batch(
212	        &self,
213	        collection: &str,
214	        batch: &[Value],
215	    ) -> Result<WriteOutcome, BatchError> {
216	        if collection.is_empty() {
217	            return Err(BatchError::Rejected(Rejection {
218	                index: 0,
219	                id: None,
220	                reason: "collection name must not be empty".to_string(),
221	            }));
222	        }
223	
224	        let mut st = self.inner.lock().unwrap();
225	
226	        // 阶段 1：逐条校验；任何失败都直接返回，状态未做任何修改。
227	        let mut seen: HashMap<&str, usize> = HashMap::with_capacity(batch.len());
228	        let mut prepared: Vec<Record> = Vec::with_capacity(batch.len());
229	        for (i, raw) in batch.iter().enumerate() {
230	            let rec = match raw {
231	                Value::Object(map) => map,
232	                _ => {
233	                    return Err(BatchError::Rejected(Rejection {
234	                        index: i,
235	                        id: None,
236	                        reason: "record must be a JSON object".to_string(),
237	                    }));
238	                }
239	            };
240	            let id = match rec.get("id") {
241	                None => {
242	                    return Err(BatchError::Rejected(Rejection {
243	                        index: i,
244	                        id: None,
245	                        reason: "missing primary key field \"id\"".to_string(),
246	                    }));
247	                }
248	                Some(Value::String(s)) if !s.is_empty() => s.as_str(),
249	                Some(Value::String(_)) => {
250	                    return Err(BatchError::Rejected(Rejection {
251	                        index: i,
252	                        id: None,
253	                        reason: "primary key \"id\" must be a non-empty string".to_string(),
254	                    }));
255	                }
256	                Some(_) => {
257	                    return Err(BatchError::Rejected(Rejection {
258	                        index: i,
259	                        id: None,
260	                        reason: "primary key \"id\" must be a string".to_string(),
261	                    }));
262	                }
263	            };
264	            if let Some(&first) = seen.get(id) {
265	                return Err(BatchError::Rejected(Rejection {
266	                    index: i,
267	                    id: Some(id.to_string()),
268	                    reason: format!(
269	                        "duplicate id \"{id}\" in the same batch (first at index {first})"
270	                    ),
271	                }));
272	            }
273	            for (field, value) in rec.iter() {
274	                if let Err(msg) = validate_value(value) {
275	                    return Err(BatchError::Rejected(Rejection {
276	                        index: i,
277	                        id: Some(id.to_string()),
278	                        reason: format!("field \"{field}\": {msg}"),
279	                    }));
280	                }
281	            }
282	            seen.insert(id, i);
283	            prepared.push(rec.clone());
284	        }
285	
286	        // 阶段 2：与集合中已有记录冲突检查——同主键但内容不同即拒绝整批。
287	        if let Some(existing) = st.current.get(collection) {
288	            for (i, rec) in prepared.iter().enumerate() {
289	                let id = rec["id"].as_str().unwrap();
290	                if let Some(old) = existing.iter().find(|r| r["id"] == id)
291	                    && old != rec
292	                {
293	                    return Err(BatchError::Rejected(Rejection {
294	                        index: i,
295	                        id: Some(id.to_string()),
296	                        reason: format!(
297	                            "collection \"{collection}\" already contains a different record with id \"{id}\""
298	                        ),
299	                    }));
300	                }
301	            }
302	        }
303	
304	        // 阶段 3：先持久化（追加 WAL 并 fsync），成功后才更新内存并确认成功。
305	        let event = CommitEvent {
306	            collection: collection.to_string(),
307	            records: prepared.clone(),
308	        };
309	        append_wal(&mut st.wal, &event).map_err(BatchError::Persist)?;
310	
311	        let existing = st.current.entry(collection.to_string()).or_default();
312	        let mut inserted = 0usize;
313	        for rec in prepared {
314	            let id = rec["id"].as_str().unwrap();
315	            match existing.iter().position(|r| r["id"] == id) {
316	                Some(pos) => existing[pos] = rec, // 内容相同：幂等写入
317	                None => {
318	                    existing.push(rec);
319	                    inserted += 1;
320	                }
321	            }
322	        }
323	
324	        Ok(WriteOutcome {
325	            collection: collection.to_string(),
326	            accepted: batch.len(),
327	            inserted,
328	        })
329	    }
330	
331	    /// 把当前各集合数据固化为只读版本，返回版本标识与保存时间。
332	    pub fn save_version(&self) -> Result<VersionSummary, String> {
333	        let mut st = self.inner.lock().unwrap();
334	        let id = st.next_id;
335	        let saved_at = now_ms();
336	        let data: HashMap<String, Vec<Record>> = st
337	            .current
338	            .iter()
339	            .map(|(name, records)| (name.clone(), records.clone()))
340	            .collect();
341	        st.versions.push(VersionSnap { id, saved_at, data });
342	        st.next_id += 1;
343	
344	        // 固化完整状态到快照文件，然后清空 WAL（旧提交已包含在快照中）。
345	        persist_state(&self.data_dir, &st)?;
346	        truncate_wal(&mut st.wal, &self.data_dir.join("wal.log"))?;
347	
348	        Ok(VersionSummary { id, saved_at })
349	    }
350	
351	    /// 查询指定版本内指定集合的全部记录（字段顺序与写入时一致）。
352	    pub fn read_records(
353	        &self,
354	        version_id: u64,
355	        collection: &str,
356	    ) -> Result<Vec<Record>, LookupError> {
357	        let st = self.inner.lock().unwrap();
358	        let version = st
359	            .versions
360	            .iter()
361	            .find(|v| v.id == version_id)
362	            .ok_or(LookupError::VersionNotFound)?;
363	        version
364	            .data
365	            .get(collection)
366	            .cloned()
367	            .ok_or(LookupError::CollectionNotFound)
368	    }
369	
370	    /// 已保存版本列表（按保存顺序）。
371	    pub fn list_versions(&self) -> Vec<VersionSummary> {
372	        let st = self.inner.lock().unwrap();
373	        st.versions
374	            .iter()
375	            .map(|v| VersionSummary {
376	                id: v.id,
377	                saved_at: v.saved_at,
378	            })
379	            .collect()
380	    }
381	
382	    /// 单个版本的详情（含集合名列表）。
383	    pub fn get_version(&self, version_id: u64) -> Result<VersionDetail, LookupError> {
384	        let st = self.inner.lock().unwrap();
385	        let v = st
386	            .versions
387	            .iter()
388	            .find(|v| v.id == version_id)
389	            .ok_or(LookupError::VersionNotFound)?;
390	        Ok(VersionDetail {
391	            id: v.id,
392	            saved_at: v.saved_at,
393	            collections: v.data.keys().cloned().collect(),
394	        })
395	    }
396	}
397	
398	/// WAL 重放/应用：按主键 upsert；整批来自同一个 commit 事件。
399	fn apply_commit(
400	    current: &mut BTreeMap<String, Vec<Record>>,
401	    collection: String,
402	    records: Vec<Record>,
403	) {
404	    let entry = current.entry(collection).or_default();
405	    for rec in records {
406	        let id = rec["id"].as_str().expect("validated commit");
407	        match entry.iter().position(|r| r["id"] == id) {
408	            Some(pos) => entry[pos] = rec,
409	            None => entry.push(rec),
410	        }
411	    }
412	}
413	
414	fn append_wal(wal: &mut fs::File, event: &CommitEvent) -> Result<(), String> {
415	    let mut line = serde_json::to_vec(event).map_err(|e| format!("encode wal: {e}"))?;
416	    line.push(b'\n');
417	    wal.write_all(&line)
418	        .and_then(|_| wal.flush())
419	        .and_then(|_| wal.sync_all())
420	        .map_err(|e| format!("wal append: {e}"))
421	}
422	
423	/// 完整状态写入 snapshot.json（临时文件 + fsync + 原子重命名 + 目录 fsync）。
424	fn persist_state(dir: &Path, st: &Inner) -> Result<(), String> {
425	    let state = PersistedState {
426	        versions: st
427	            .versions
428	            .iter()
429	            .map(|v| PersistedVersion {
430	                id: v.id,
431	                saved_at: v.saved_at,
432	                collections: v
433	                    .data
434	                    .iter()
435	                    .map(|(name, records)| PersistedCollection {
436	                        name: name.clone(),
437	                        records: records.clone(),
438	                    })
439	                    .collect(),
440	            })
441	            .collect(),
442	        collections: st
443	            .current
444	            .iter()
445	            .map(|(name, records)| PersistedCollection {
446	                name: name.clone(),
447	                records: records.clone(),
448	            })
449	            .collect(),
450	    };
451	    let mut bytes = serde_json::to_vec(&state).map_err(|e| format!("encode snapshot: {e}"))?;
452	    bytes.push(b'\n');
453	
454	    let target = dir.join("snapshot.json");
455	    let tmp = dir.join("snapshot.json.tmp");
456	    {
457	        let mut f = fs::OpenOptions::new()
458	            .create(true)
459	            .write(true)
460	            .truncate(true)
461	            .open(&tmp)
462	            .map_err(|e| format!("write snapshot tmp: {e}"))?;
463	        f.write_all(&bytes)
464	            .and_then(|_| f.flush())
465	            .and_then(|_| f.sync_all())
466	            .map_err(|e| format!("write snapshot tmp: {e}"))?;
467	    }
468	    fs::rename(&tmp, &target).map_err(|e| format!("rename snapshot: {e}"))?;
469	    if let Ok(d) = fs::File::open(dir) {
470	        let _ = d.sync_all();
471	    }
472	    Ok(())
473	}
474	
475	/// 清空 WAL（其中的提交已固化进 snapshot.json），并重新以追加模式打开。
476	fn truncate_wal(wal: &mut fs::File, wal_path: &Path) -> Result<(), String> {
477	    {
478	        let mut f = fs::OpenOptions::new()
479	            .create(true)
480	            .write(true)
481	            .truncate(true)
482	            .open(wal_path)
483	            .map_err(|e| format!("truncate wal: {e}"))?;
484	        f.flush()
485	            .and_then(|_| f.sync_all())
486	            .map_err(|e| format!("truncate wal: {e}"))?;
487	    }
488	    // 先关闭旧句柄，再以 append 重新打开供后续提交使用。
489	    let reopened = fs::OpenOptions::new()
490	        .append(true)
491	        .open(wal_path)
492	        .map_err(|e| format!("reopen wal: {e}"))?;
493	    *wal = reopened;
494	    Ok(())
495	}
496	
497	/// 递归校验字段值：仅允许字符串、整数、布尔、null 与嵌套对象；
498	/// 浮点数与数组一律拒绝。
499	fn validate_value(v: &Value) -> Result<(), String> {
500	    match v {
501	        Value::Null | Value::Bool(_) | Value::String(_) => Ok(()),
502	        Value::Number(n) if n.is_i64() || n.is_u64() => Ok(()),
503	        Value::Number(_) => Err("number must be an integer".to_string()),
504	        Value::Object(map) => {
505	            for (k, child) in map {
506	                validate_value(child).map_err(|e| format!("{k}: {e}"))?;
507	            }
508	            Ok(())
509	        }
510	        Value::Array(_) => Err("arrays are not allowed".to_string()),
511	    }
512	}
513	
514	#[cfg(test)]
515	mod unit_tests {
516	    use super::*;
517	    use serde_json::json;
518	
519	    fn temp_dir() -> PathBuf {
520	        use std::sync::atomic::{AtomicU64, Ordering};
521	        static SEQ: AtomicU64 = AtomicU64::new(0);
522	        let mut dir = std::env::temp_dir();
523	        let nanos = SystemTime::now()
524	            .duration_since(UNIX_EPOCH)
525	            .unwrap()
526	            .as_nanos();
527	        let seq = SEQ.fetch_add(1, Ordering::Relaxed);
528	        dir.push(format!("vde-test-{}-{nanos}-{seq}", std::process::id()));
529	        dir
530	    }
531	
532	    #[test]
533	    fn rejects_batch_atomically_with_detailed_reason() {
534	        let dir = temp_dir();
535	        let store = Store::open(&dir).unwrap();
536	        let ok = store
537	            .write_batch("users", &[json!({"id": "u1", "name": "Ada", "age": 36})])
538	            .unwrap();
539	        assert_eq!(ok.inserted, 1);
540	
541	        // 第二条非法，整批拒绝；u2 不得残留。
542	        let err = store
543	            .write_batch(
544	                "users",
545	                &[
546	                    json!({"id": "u2", "score": 100}),
547	                    json!({"id": "u3", "score": 9.5}),
548	                ],
549	            )
550	            .unwrap_err();
551	        match err {
552	            BatchError::Rejected(r) => {
553	                assert_eq!(r.index, 1);
554	                assert_eq!(r.id.as_deref(), Some("u3"));
555	                assert!(r.reason.contains("integer"));
556	            }
557	            BatchError::Persist(e) => panic!("{e}"),
558	        }
559	
560	        // 缺主键。
561	        let err = store
562	            .write_batch("users", &[json!({"name": "NoId"})])
563	            .unwrap_err();
564	        match err {
565	            BatchError::Rejected(r) => assert!(r.reason.contains("missing primary key")),
566	            _ => panic!(),
567	        }
568	
569	        // 同批重复主键。
570	        let err = store
571	            .write_batch("users", &[json!({"id": "d1"}), json!({"id": "d1"})])
572	            .unwrap_err();
573	        match err {
574	            BatchError::Rejected(r) => assert!(r.reason.contains("duplicate id")),
575	            _ => panic!(),
576	        }
577	
578	        // 同主键不同内容 → 拒绝。
579	        let err = store
580	            .write_batch("users", &[json!({"id": "u1", "name": "Ada", "age": 37})])
581	            .unwrap_err();
582	        match err {
583	            BatchError::Rejected(r) => assert!(r.reason.contains("different record")),
584	            _ => panic!(),
585	        }
586	
587	        // 数组字段拒绝。
588	        let err = store
589	            .write_batch("users", &[json!({"id": "u4", "tags": ["a"]})])
590	            .unwrap_err();
591	        match err {
592	            BatchError::Rejected(r) => assert!(r.reason.contains("arrays")),
593	            _ => panic!(),
594	        }
595	
596	        // u2 未写入。
597	        let v = store.save_version().unwrap();
598	        let recs = store.read_records(v.id, "users").unwrap();
599	        assert_eq!(recs.len(), 1);
600	
601	        fs::remove_dir_all(&dir).ok();
602	    }
