604	    #[test]
605	    fn snapshots_are_immutable_and_field_order_preserved() {
606	        let dir = temp_dir();
607	        let store = Store::open(&dir).unwrap();
608	        store
609	            .write_batch(
610	                "users",
611	                &[json!({"id": "u1", "z": 1, "a": true, "nested": {"y": 2, "b": null}})],
612	            )
613	            .unwrap();
614	        let v1 = store.save_version().unwrap();
615	
616	        // 覆盖写入并清空式替换（同内容幂等，不同内容拒绝，用新集合模拟后续变化）。
617	        store
618	            .write_batch("users", &[json!({"id": "u2", "x": 2})])
619	            .unwrap();
620	        let _v2 = store.save_version().unwrap();
621	
622	        let old = store.read_records(v1.id, "users").unwrap();
623	        assert_eq!(old.len(), 1);
624	        let keys: Vec<_> = old[0].keys().cloned().collect();
625	        assert_eq!(keys, vec!["id", "z", "a", "nested"]);
626	        let nested: Vec<_> = old[0]["nested"]
627	            .as_object()
628	            .unwrap()
629	            .keys()
630	            .cloned()
631	            .collect();
632	        assert_eq!(nested, vec!["y", "b"]);
633	
634	        assert!(matches!(
635	            store.read_records(999, "users"),
636	            Err(LookupError::VersionNotFound)
637	        ));
638	        assert!(matches!(
639	            store.read_records(v1.id, "missing"),
640	            Err(LookupError::CollectionNotFound)
641	        ));
642	
643	        fs::remove_dir_all(&dir).ok();
644	    }
645	
646	    #[test]
647	    fn recovers_state_after_restart() {
648	        let dir = temp_dir();
649	        let v1_id;
650	        {
651	            let store = Store::open(&dir).unwrap();
652	            store
653	                .write_batch("users", &[json!({"id": "u1", "v": 1})])
654	                .unwrap();
655	            v1_id = store.save_version().unwrap().id;
656	            store
657	                .write_batch("users", &[json!({"id": "u2", "v": 2})])
658	                .unwrap();
659	        }
660	        // 重新打开：旧版本数据与保存后的 WAL 提交都应可见。
661	        let store = Store::open(&dir).unwrap();
662	        let recs = store.read_records(v1_id, "users").unwrap();
663	        assert_eq!(recs.len(), 1);
664	        let versions = store.list_versions();
665	        assert_eq!(versions.len(), 1);
666	        let v2 = store.save_version().unwrap();
667	        assert_eq!(store.read_records(v2.id, "users").unwrap().len(), 2);
668	
669	        fs::remove_dir_all(&dir).ok();
670	    }
