672	    #[test]
673	    fn truncated_wal_tail_is_discarded() {
674	        let dir = temp_dir();
675	        {
676	            let store = Store::open(&dir).unwrap();
677	            store.write_batch("users", &[json!({"id": "u1"})]).unwrap();
678	            store.save_version().unwrap();
679	            store.write_batch("users", &[json!({"id": "u2"})]).unwrap();
680	        }
681	        // 模拟崩溃：追加一段不完整的行。
682	        let wal_path = dir.join("wal.log");
683	        use std::io::Write as _;
684	        let mut f = fs::OpenOptions::new().append(true).open(&wal_path).unwrap();
685	        f.write_all(b"{\"collection\":\"users\",\"records\":[{\"id\":\"ghost\"}")
686	            .unwrap();
687	        f.sync_all().unwrap();
688	        drop(f);
689	
690	        let store = Store::open(&dir).unwrap();
691	        let v = store.save_version().unwrap();
692	        let recs = store.read_records(v.id, "users").unwrap();
693	        let ids: Vec<_> = recs.iter().map(|r| r["id"].as_str().unwrap()).collect();
694	        assert_eq!(ids, vec!["u1", "u2"]);
695	
696	        fs::remove_dir_all(&dir).ok();
697	    }
