353	    let s = Arc::new(spawn_server().await);
354	    let writers = 8usize;
355	    let batches = 12usize;
356	    let batch_size = 5usize;
357	
358	    let mut handles = Vec::new();
359	    for w in 0..writers {
360	        let addr = s.addr.clone();
361	        handles.push(tokio::spawn(async move {
362	            for b in 0..batches {
363	                let mut recs = String::from("[");
364	                for i in 0..batch_size {
365	                    if i > 0 {
366	                        recs.push(',');
367	                    }
368	                    recs.push_str(&format!(
369	                        "{{\"id\":\"w{w}-b{b}-r{i}\",\"w\":{w},\"b\":{b},\"i\":{i}}}"
370	                    ));
371	                }
372	                recs.push(']');
373	                let payload = format!(r#"{{"records":{recs}}}"#);
374	                let addr2 = addr.clone();
375	                let r = tokio::task::spawn_blocking(move || {
376	                    request(&addr2, "POST", "/collections/items/records", Some(&payload))
377	                })
378	                .await
379	                .unwrap();
380	                assert_eq!(r.status, 200, "batch {w}/{b}: {}", r.body);
381	            }
382	        }));
383	    }
384	
385	    // 并发持续保存快照。
386	    let saver_addr = s.addr.clone();
387	    let saver = tokio::spawn(async move {
388	        let mut saved = Vec::new();
389	        for _ in 0..20 {
390	            let addr2 = saver_addr.clone();
391	            let r = tokio::task::spawn_blocking(move || request(&addr2, "POST", "/versions", None))
392	                .await
393	                .unwrap();
394	            assert_eq!(r.status, 201);
395	            saved.push(r.body["id"].as_u64().unwrap());
396	            tokio::time::sleep(std::time::Duration::from_millis(2)).await;
397	        }
398	        saved
399	    });
400	
401	    for h in handles {
402	        h.await.unwrap();
403	    }
404	    let saved = saver.await.unwrap();
405	
406	    // 每个快照中，任一批次要么完整出现、要么完全不出现。
407	    for vid in saved {
408	        let addr = s.addr.clone();
409	        let r = tokio::task::spawn_blocking(move || {
410	            request(
411	                &addr,
412	                "GET",
413	                &format!("/versions/{vid}/collections/items/records"),
414	                None,
415	            )
416	        })
417	        .await
418	        .unwrap();
419	        assert_eq!(r.status, 200);
420	        // 以 (w,b) 分组计数，每个已出现的批次必须是完整的 batch_size 条。
421	        let mut counts = std::collections::HashMap::new();
422	        for rec in r.body["records"].as_array().unwrap() {
423	            let key = (rec["w"].as_u64().unwrap(), rec["b"].as_u64().unwrap());
424	            *counts.entry(key).or_insert(0u64) += 1;
425	        }
426	        for ((w, b), n) in &counts {
427	            assert_eq!(
428	                *n, batch_size as u64,
429	                "half batch w{w} b{b}: {n}/{batch_size}"
430	            );
431	        }
432	    }
433	
434	    // 最终全部写入均可见（无丢失的已确认批次）。
435	    let r = request(&s.addr, "POST", "/versions", None);
436	    let final_v = r.body["id"].as_u64().unwrap();
437	    let r = request(
438	        &s.addr,
439	        "GET",
440	        &format!("/versions/{final_v}/collections/items/records"),
441	        None,
442	    );
443	    assert_eq!(
444	        r.body["records"].as_array().unwrap().len(),
445	        writers * batches * batch_size
446	    );
447	}
